"use client";

/**
 * /signout (2026-10-28): signs out the same way Settings does, then goes to
 * the sign-in page. The Fullscreen pages (/IS/, static files with no React)
 * send their "Sign out" here. Not generated by scripts/port-pages.mjs.
 */
import { useEffect } from "react";
import { signOut } from "../lib/averages";

export default function SignOutPage() {
  useEffect(() => {
    signOut()
      .catch(() => {})
      // ?signedout: the front door (worker/index.js) answers with Clear-Site-Data, wiping what's left (2026-11-06)
      .finally(() => window.location.replace("/?signedout=1"));
  }, []);
  return null;
}
